 for(double rate:{32000.,44100.,48000.,88200.,96000.,176400.,192000.}){Element246VoiceInput stream;stream.prepare(rate);for(int n=0;n<1024;++n)stream.next(true,float(.3*std::sin(n*.071)));check(stream.input==uint64_t(std::floor(1023/stream.ratio+1.e-9))+1,"External voice clock loses samples");stream.next(false,0);check(!stream.active&&stream.head==0&&std::all_of(stream.words.begin(),stream.words.end(),[](int16_t x){return x==0;}),"External voice disable retains history");for(float input:{std::numeric_limits<float>::quiet_NaN(),std::numeric_limits<float>::infinity()})stream.next(true,input);check(std::isfinite(stream.previous),"External voice non-finite input escapes guard");}
 {Element246VoiceInput stream;stream.prepare(44100);for(int n=0;n<81;++n)stream.next(true,float(n-32)/32768.f);Bend246Voice bridge;bridge.configure(true,0,24000,0,true,3,3,&stream.words,stream.head);std::array<uint32_t,128> pitch{};pitch.fill(12345678);bridge.pitchBlock(pitch);stream.words.fill(0);for(int i=0;i<128;++i)check(bridge.amplitude(12000)==reference::saturate16(12000+reference::multiplyQ15(int16_t(i/2-15),24000)),"External voice paired capture changed inside block");check(pitch[0]==12345678,"Element gain changes pitch");bridge.configure(true,0,16000,0,true,1);check(!bridge.started&&bridge.owner==1,"Element capture leaks into Bend owner");}
